for (const locale of Object.keys(ownerAppMessages)) messages[locale].ownerApp = ownerAppMessages[locale];

const storedLocale = typeof window === 'undefined' ? null : window.localStorage.getItem('ccps-locale');
export const i18n = createI18n({ legacy: false, globalInjection: true, locale: supportedLocales.some((item) => item.code === storedLocale) ? storedLocale : 'zh-CN', fallbackLocale: 'zh-CN', messages });

const legacyKeyByText = new Map();
for (const locale of ['zh-CN', 'zh-TW', 'en']) {
  for (const [key, value] of Object.entries(messages[locale].legacy || {})) {
    const text = String(value || '').trim();
    if (text && !legacyKeyByText.has(text)) legacyKeyByText.set(text, key);
  }
}

// Transitional bridge for runtime labels that must remain stable business
// values (filters/status maps) but still need locale-aware presentation.
export const translateLegacyText = (value, params) => {
  if (value === null || value === undefined || typeof value !== 'string') return value;
  const key = legacyKeyByText.get(value.trim());
  return key ? i18n.global.t(`legacy.${key}`, params) : value;
};

const translateLegacyFragment = (part) => {
  const match = String(part).match(/^(\s*)([\s\S]*?)(\s*)$/);
  return `${match[1]}${translateLegacyText(match[2])}${match[3]}`;
};

export const translateLegacyTemplate = (strings, ...values) => strings.reduce((result, part, index) => {
  const value = index < values.length && typeof values[index] === 'string'
    ? translateLegacyText(values[index])
    : values[index] ?? '';
  return `${result}${translateLegacyFragment(part)}${value}`;
}, '');

export const localizeLegacyTree = (value) => {
  if (typeof value === 'string') return translateLegacyText(value);
  if (Array.isArray(value)) return value.map(localizeLegacyTree);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, localizeLegacyTree(item)]));
};

export const regionDisplayName = (code) => {
  const region = String(code || '').toUpperCase();
  if (!region) return '';
  try {
    return new Intl.DisplayNames([i18n.global.locale.value], { type: 'region' }).of(region) || region;
  } catch {
    return region;
  }
};

export const setLocale = (locale) => {
  if (!supportedLocales.some((item) => item.code === locale)) return;
  i18n.global.locale.value = locale;
  if (typeof window !== 'undefined') {
    window.localStorage.setItem('ccps-locale', locale);
    document.documentElement.lang = locale;
  }
};

if (typeof document !== 'undefined') document.documentElement.lang = i18n.global.locale.value;
